"""Offline, same-origin dashboard shared by desktop and phone browsers."""

MOBILE_PAGE = r'''<!doctype html>
<html lang="zh-CN">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="color-scheme" content="light"><title>微信工作台 · 可视化控制</title>
<style>
:root{--ink:#132c36;--muted:#61757b;--green:#11856b;--line:#dce5e2;--bg:#f3f6f5;--red:#ae3c40}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.6 "Segoe UI","Microsoft YaHei",sans-serif}button,input,select{font:inherit}button{cursor:pointer;min-height:44px;border:1px solid var(--line);border-radius:9px;padding:9px 16px;background:white;color:var(--ink);font-weight:600}button:hover{border-color:var(--green);background:#eef7f3}button:active{background:#dceee6}button.primary{background:var(--green);color:white;border-color:var(--green)}button.danger{color:var(--red)}button:disabled{opacity:.45;cursor:not-allowed}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #51bda1;outline-offset:3px}.shell{max-width:1440px;margin:auto;display:grid;grid-template-columns:216px minmax(0,1fr);min-height:100vh}.sidebar{background:var(--ink);color:white;padding:32px 22px;display:flex;flex-direction:column}.brand{font-size:22px;letter-spacing:.04em;font-weight:700}.edition{color:#98b6b7;font-size:12px;margin:4px 0 34px}.nav{display:grid;gap:8px}.nav button{border:0;text-align:left;background:transparent;color:#b5cccb;font-weight:500;padding:12px}.nav button[aria-selected=true]{background:#24434b;color:white}.nav span{margin-right:12px;color:#6faaa0}.rail-note{margin-top:auto;padding-top:40px;font-size:12px;color:#a0b8ba}.rail-note strong{color:#d9eeea;display:block;margin-bottom:8px}.main{padding:34px 38px}.eyebrow{color:var(--green);letter-spacing:.08em;font-size:11px;font-weight:700}.top{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:24px}h1{font-size:28px;line-height:1.3;letter-spacing:-.04em;margin:6px 0}h2{font-size:17px;margin:0}h3{font-size:15px;margin:0}.sub{color:var(--muted);font-size:13px;margin:6px 0}.status-pill{padding:7px 12px;border:1px solid var(--line);border-radius:30px;font-size:12px;background:white;white-space:nowrap}.status-pill::before{content:"";display:inline-block;width:7px;height:7px;background:#8ca09f;border-radius:50%;margin-right:7px}.status-pill.online::before{background:var(--green)}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-bottom:26px}.metric{padding:18px 22px;border:1px solid var(--line);border-radius:12px;background:white}.metric small{color:var(--muted);font-size:12px}.metric strong{display:block;font-size:28px;line-height:1.35;font-weight:600;margin-top:4px}.metric .detail{font-size:12px;color:var(--muted);min-height:19px}.workspace{display:grid;grid-template-columns:minmax(0,1.12fr) minmax(0,1fr);gap:22px;align-items:start}.panel{background:white;border:1px solid var(--line);border-radius:12px;overflow:hidden}.panel-head{padding:19px 22px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;gap:12px}.panel-body{padding:22px}.task{padding:18px 22px;border-bottom:1px solid #eaf0ed}.task:last-child{border:0}.task-top{display:flex;gap:16px;align-items:start;justify-content:space-between}.task-name{display:flex;align-items:center;gap:9px}.task-dot{width:7px;height:7px;border-radius:50%;background:#b8c8c4;flex:none}.task-dot.running{background:var(--green)}.task .sub{margin:5px 0 0 16px}.task-state{margin:7px 0 0 16px;font-size:12px;color:var(--green)}.task-state.failed{color:var(--red)}.task button{min-width:64px;padding:7px 12px}.empty{padding:30px 22px;color:var(--muted);font-size:13px}.log-toolbar{padding:13px 22px;display:flex;gap:10px;align-items:center}select,input{border:1px solid var(--line);padding:9px 11px;border-radius:8px;min-height:44px;background:white;color:var(--ink);max-width:100%}.log-toolbar select{flex:1;min-width:0}pre{font:12px/1.9 Consolas,"Microsoft YaHei",monospace;white-space:pre-wrap;overflow-wrap:anywhere;margin:0;background:#142e37;color:#c1e4d9;min-height:320px;max-height:510px;overflow:auto;padding:22px}.log-foot{padding:10px 22px;color:var(--muted);font-size:11px}.banner{margin-bottom:20px;padding:12px 16px;background:#e7f3ed;border-left:3px solid var(--green);font-size:13px;overflow-wrap:anywhere}.banner.error{background:#faeceb;color:#8c3036;border-color:var(--red)}[hidden]{display:none!important}.section-intro{margin-bottom:18px}.actions{display:flex;gap:10px;flex-wrap:wrap}.label{font-size:12px;color:var(--muted);display:block;margin-bottom:6px}.field{margin-bottom:16px}.field input{width:100%}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 20px}.device{display:flex;justify-content:space-between;align-items:center;padding:16px 0;border-bottom:1px solid var(--line);gap:12px}.device:last-child{border:0}.code{font-family:Consolas,monospace;overflow-wrap:anywhere}.sdk-grid{display:grid;grid-template-columns:1fr 1fr;gap:22px}.hint{background:#f3f7f5;border:1px solid var(--line);border-radius:9px;padding:14px;margin:16px 0;color:var(--muted);font-size:12px}.key-value{display:grid;grid-template-columns:96px minmax(0,1fr);gap:9px;font-size:13px;margin:15px 0}.key-value dt{color:var(--muted)}.key-value dd{margin:0;overflow-wrap:anywhere}.plugin{padding:16px 0;border-bottom:1px solid var(--line)}.plugin .actions{margin-top:10px}.footer{margin-top:28px;display:flex;gap:12px;justify-content:space-between;color:var(--muted);font-size:11px;flex-wrap:wrap}.footer a{color:var(--green)}
@media(max-width:1100px){.main{padding:26px}.shell{grid-template-columns:180px minmax(0,1fr)}.workspace{grid-template-columns:1fr}pre{min-height:220px}.sdk-grid{grid-template-columns:1fr}}@media(max-width:650px){.shell{display:block}.sidebar{padding:18px 18px 0}.brand{font-size:20px}.edition{margin:0 0 15px}.nav{display:flex;overflow:auto;gap:4px}.nav button{white-space:nowrap;border-radius:8px 8px 0 0;padding:10px 12px;font-size:13px}.nav span{display:none}.rail-note{display:none}.main{padding:22px 16px}.top{gap:8px;align-items:start;margin-bottom:18px}h1{font-size:24px}.top .sub{max-width:230px}.status-pill{font-size:11px;padding:6px 9px}.metrics{gap:8px;margin-bottom:18px}.metric{padding:13px 12px;border-radius:9px}.metric strong{font-size:24px}.metric small{font-size:11px}.metric .detail{font-size:10px}.panel-head,.panel-body{padding:17px}.task{padding:17px}.form-grid{grid-template-columns:1fr}.task .sub{font-size:12px}.footer{margin-top:20px}.key-value{grid-template-columns:80px minmax(0,1fr)}}
</style></head>
<body><div class="shell">
<aside class="sidebar"><div class="brand">微信工作台</div><div class="edition">LOCAL WORKSPACE / 网页版</div>
<nav class="nav" role="tablist" aria-label="工作区"><button role="tab" id="tab-tasks" aria-controls="view-tasks" aria-selected="true" data-view="tasks"><span>01</span>任务控制</button><button role="tab" id="tab-sdk" aria-controls="view-sdk" aria-selected="false" data-view="sdk"><span>02</span>微信与插件</button><button role="tab" id="tab-devices" aria-controls="view-devices" aria-selected="false" data-view="devices"><span>03</span>设备连接</button><button role="tab" id="tab-settings" aria-controls="view-settings" aria-selected="false" data-view="settings"><span>04</span>运行参数</button></nav>
<div class="rail-note"><strong>电脑 · 手机 · 同一工作区</strong>手机与电脑连接同一局域网，即可使用相同的任务、参数和日志。<br><br>官方微信扫码登录<br>独立 C# SDK 与插件宿主</div></aside>
<main class="main"><header class="top"><div><div class="eyebrow">CONTROL CENTER</div><h1 id="page-title">任务控制</h1><p class="sub">查看每个任务的状态，让操作有迹可循。</p></div><div id="connection" class="status-pill" role="status">正在连接</div></header>
<div id="notice" class="banner" role="status" hidden></div>
<div class="metrics"><div class="metric"><small>运行中任务</small><strong id="running">—</strong><div class="detail" id="total">等待服务响应</div></div><div class="metric"><small>服务已运行</small><strong id="uptime">—</strong><div class="detail" id="version">版本读取中</div></div><div class="metric"><small>当前连接</small><strong style="font-size:17px;margin-top:10px" id="host">—</strong><div class="detail" id="sync">尚未同步</div></div></div>
<section id="view-tasks" role="tabpanel" aria-labelledby="tab-tasks"><div class="workspace"><div class="panel"><div class="panel-head"><h2>自动化任务</h2><span class="sub">执行状态实时同步</span></div><div id="tasks"><div class="empty">正在读取任务…</div></div></div><div class="panel"><div class="panel-head"><h2>运行日志</h2><button id="copy-log">复制日志</button></div><div class="log-toolbar"><label for="log-task" class="label">查看任务</label><select id="log-task" aria-label="选择日志任务"></select></div><pre id="log" tabindex="0" aria-label="任务日志">连接后显示真实任务日志。</pre><div class="log-foot">保留最近 80 行 · 每 3 秒同步</div></div></div></section>
<section id="view-sdk" role="tabpanel" aria-labelledby="tab-sdk" hidden><div class="section-intro"><h2>连接官方微信，使用 C# SDK</h2><p class="sub">后台宿主运行 SDK 和扩展；登录仍在官方微信窗口中由你扫码完成。</p></div><div class="sdk-grid"><div class="panel"><div class="panel-head"><h2>微信会话</h2><button id="sdk-refresh">刷新状态</button></div><div class="panel-body"><div id="sdk-state" class="status-pill">未检查 SDK 宿主</div><dl id="sdk-info" class="key-value"></dl><div class="actions"><button id="sdk-start" class="primary">启动 SDK 宿主</button><button id="sdk-login">打开微信登录</button><button id="sdk-stop" class="danger">停止宿主</button></div><p class="hint">请保留官方微信桌面窗口。UI 自动化可能需要可见窗口及交互桌面，不能保证锁屏后继续操作。停止宿主不会退出官方微信。</p></div></div><div class="panel"><div class="panel-head"><h2>独立插件</h2><span class="sub">本机扩展宿主</span></div><div class="panel-body"><div id="plugins" class="sub">刷新状态后显示已安装插件。</div><pre id="plugin-result" style="min-height:120px;margin-top:16px" tabindex="0">等待执行插件诊断。</pre><p class="sub">插件在本机独立进程中使用公开 SDK 接口；此版本未向微信进程注入代码。</p></div></div></div></section>
<section id="view-devices" role="tabpanel" aria-labelledby="tab-devices" hidden><div class="panel"><div class="panel-head"><h2>安卓设备</h2><button id="devices-refresh">重新检测</button></div><div class="panel-body"><p class="sub">通过电脑端内置 ADB 检测。真机需连接 USB 并开启 USB 调试。</p><div id="devices" class="empty">尚未检测设备。</div><details><summary>查看检测输出</summary><pre id="device-raw" style="min-height:100px;margin-top:12px"></pre></details></div></div></section>
<section id="view-settings" role="tabpanel" aria-labelledby="tab-settings" hidden><div class="panel"><div class="panel-head"><h2>运行参数</h2><button id="settings-reload">重新读取</button></div><form class="panel-body" id="settings-form"><p class="sub">参数保存在电脑端，新启动的任务使用已保存参数。</p><div class="form-grid"><label class="field"><span class="label">每轮点赞数量</span><input name="round_like_count" type="number" min="1" max="1000" required></label><label class="field"><span class="label">每轮休息 / 分钟</span><input name="round_rest_minutes" type="number" min="1" max="1440" required></label><label class="field"><span class="label">每日开始 / 小时 0–23</span><input name="run_start_hour" type="number" min="0" max="23" required></label><label class="field"><span class="label">每日结束 / 小时 0–23</span><input name="run_end_hour" type="number" min="0" max="23" required></label><label class="field"><span class="label">多开微信数量</span><input name="wechat_count" type="number" min="1" max="10" required></label><label class="field"><span class="label">ADB 服务端口</span><input name="adb_port" type="number" min="1" max="65535" required></label><label class="field"><span class="label">定点点赞 · 作者</span><input name="replica_author" maxlength="200"></label><label class="field"><span class="label">定点点赞 · 关键词</span><input name="replica_keyword" maxlength="200"></label></div><div class="actions"><button type="submit" class="primary" id="save-settings">保存到电脑</button></div><p class="sub" id="settings-state" role="status">首次进入时读取电脑端配置。</p></form></div></section>
<footer class="footer"><span>本机服务 · <span id="footer-url"></span></span><a href="https://dotnet.microsoft.com/zh-cn/learn/maui/first-app-tutorial/intro?initial-os=windows" target="_blank" rel="noopener">继续 .NET MAUI 官方教程 ↗</a><span>仅供学习研究</span></footer></main></div>
<script>
'use strict';
const $=id=>document.getElementById(id);let connected=false,refreshing=false,taskCache=[],currentView='tasks',configLoaded=false,sdkBusy=false,deviceBusy=false;const busyTasks=new Set();
$('footer-url').textContent=location.host;$('host').textContent=location.hostname;
function notice(message,error=false){$('notice').hidden=!message;$('notice').textContent=message;$('notice').className='banner'+(error?' error':'');}
async function api(path,body){const requestTimeout=path==='/api/sdk/contacts'||path==='/api/sdk/ai/preview'||path==='/api/sdk/plugins/run'?115000:12000;const r=await fetch(path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body),signal:AbortSignal.timeout(requestTimeout)});let data;try{data=await r.json()}catch{throw new Error('服务响应无法读取')}if(!r.ok||!data.ok)throw new Error(data.message||'请求失败（'+r.status+'）');return data;}
function el(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;}
function connection(ok){connected=ok;$('connection').textContent=ok?'服务已连接':'连接已断开';$('connection').className='status-pill'+(ok?' online':'');document.querySelectorAll('[data-task]').forEach(b=>b.disabled=!ok||busyTasks.has(b.dataset.task));$('save-settings').disabled=!ok;}
function duration(s){return s<60?s+' 秒':s<3600?Math.floor(s/60)+' 分钟':Math.floor(s/3600)+' 小时 '+Math.floor(s%3600/60)+' 分';}
function renderTasks(tasks){taskCache=tasks;const focusId=document.activeElement?.dataset?.task;$('tasks').replaceChildren();for(const t of tasks){const item=el('article',undefined,'task'),row=el('div',undefined,'task-top'),body=el('div'),title=el('div',undefined,'task-name');title.append(el('i',undefined,'task-dot'+(t.running?' running':'')),el('h3',t.name));body.append(title,el('p',t.desc,'sub'));const failed=!t.running&&t.exit_code!=null&&t.exit_code!==0;body.append(el('p',t.running?'运行中 · '+duration(t.elapsed||0):failed?'执行退出 · 代码 '+t.exit_code:t.exit_code===0?'执行已结束':'等待运行','task-state'+(failed?' failed':'')));const button=el('button',t.running?'停止':'开始',t.running?'danger':'primary');button.dataset.task=t.id;button.disabled=!connected||busyTasks.has(t.id);button.setAttribute('aria-label',(t.running?'停止':'开始')+t.name);button.onclick=()=>taskAction(t);row.append(body,button);item.append(row);$('tasks').append(item);if(focusId===t.id)button.focus({preventScroll:true});}if(!tasks.length)$('tasks').append(el('div','电脑端没有可用任务。','empty'));const selection=$('log-task').value;const ids=tasks.map(t=>t.id).join('|');if($('log-task').dataset.ids!==ids){$('log-task').replaceChildren(...tasks.map(t=>{const o=el('option',t.name);o.value=t.id;return o;}));$('log-task').dataset.ids=ids;if(tasks.some(t=>t.id===selection))$('log-task').value=selection;}}
async function refresh(){if(refreshing||document.hidden)return;refreshing=true;try{const s=await api('/api/status');connection(true);$('running').textContent=s.tasks.filter(t=>t.running).length;$('total').textContent=s.tasks.length+' 个可用任务';$('uptime').textContent=duration(s.uptime||0);$('version').textContent='控制台 v'+s.version;$('sync').textContent='同步于 '+new Date().toLocaleTimeString('zh-CN');renderTasks(s.tasks);if(currentView==='tasks')await loadLogs();}catch(e){connection(false);$('sync').textContent='等待重新连接';notice('无法连接电脑端：'+e.message+'。服务恢复后会自动重试。',true);}finally{refreshing=false;}}
async function loadLogs(){const id=$('log-task').value;if(!id)return;const s=await api('/api/logs?task='+encodeURIComponent(id)+'&n=80');if(id!==$('log-task').value)return;const text=s.lines.length?s.lines.join('\n'):'暂无日志。启动此任务后将在这里显示输出。';if($('log').textContent!==text){const follow=$('log').scrollHeight-$('log').scrollTop-$('log').clientHeight<30;$('log').textContent=text;if(follow)$('log').scrollTop=$('log').scrollHeight;}}
async function taskAction(t){if(busyTasks.has(t.id))return;busyTasks.add(t.id);renderTasks(taskCache);try{const r=await api('/api/task/'+(t.running?'stop':'start'),{task:t.id});notice(r.message||'操作已完成');$('log-task').value=t.id;await refresh();}catch(e){notice(e.message,true);}finally{busyTasks.delete(t.id);renderTasks(taskCache);}}
async function devices(){if(deviceBusy)return;deviceBusy=true;$('devices-refresh').disabled=true;$('devices').textContent='正在检测…';try{const d=await api('/api/devices');$('devices').replaceChildren();for(const serial of d.devices){const row=el('div',undefined,'device');row.append(el('span',typeof serial==='string'?serial:JSON.stringify(serial),'code'),el('span','ADB 已连接','sub'));$('devices').append(row);}if(!d.devices.length)$('devices').textContent='未发现已连接设备，请检查 USB 线和调试授权。';$('device-raw').textContent=d.raw||'没有检测输出';}catch(e){$('devices').textContent='检测失败：'+e.message;notice(e.message,true);}finally{deviceBusy=false;$('devices-refresh').disabled=false;}}
async function loadConfig(){try{const d=await api('/api/config');for(const [key,value]of Object.entries(d.config)){const input=$('settings-form').elements.namedItem(key);if(input)input.value=value??'';}configLoaded=true;$('settings-state').textContent='已读取电脑端配置。';}catch(e){$('settings-state').textContent='读取失败：'+e.message;notice(e.message,true);}}
$('settings-form').onsubmit=async e=>{e.preventDefault();const values={};for(const [key,value]of new FormData(e.target)){values[key]=key==='adb_port'?String(value):['replica_author','replica_keyword'].includes(key)?value:Number(value);}$('save-settings').disabled=true;try{await api('/api/config',values);$('settings-state').textContent='已保存 · '+new Date().toLocaleTimeString('zh-CN');notice('运行参数已保存到电脑端。');}catch(err){$('settings-state').textContent='保存失败：'+err.message;notice(err.message,true);}finally{$('save-settings').disabled=!connected;}};
function sdkInfo(key,value){$('sdk-info').append(el('dt',key),el('dd',value));}
async function sdkStatus(){if(sdkBusy)return;sdkBusy=true;$('sdk-refresh').disabled=true;try{const d=await api('/api/sdk/status');$('sdk-state').textContent=d.running?'SDK 宿主运行中':'SDK 宿主未启动';$('sdk-state').className='status-pill'+(d.running?' online':'');$('sdk-info').replaceChildren();sdkInfo('服务地址',d.url||'本机 127.0.0.1:18766');sdkInfo('连接说明',d.message||(d.running?'可以检测微信会话或运行插件。':'点击启动 SDK 宿主。'));if(d.session){sdkInfo('微信会话',d.session.message||d.session.state||JSON.stringify(d.session));}const p=Array.isArray(d.plugins)?{plugins:d.plugins}:d.running?await api('/api/sdk/plugins'):{plugins:[]};const list=p.plugins||[];$('plugins').replaceChildren();for(const plugin of list){const row=el('div',undefined,'plugin');row.append(el('h3',plugin.name||plugin.id),el('p',plugin.description||'本机 SDK 扩展','sub'));const actions=el('div',undefined,'actions'),run=el('button','运行诊断');run.onclick=async()=>{run.disabled=true;try{const r=await api('/api/sdk/plugins/run',{id:plugin.id});$('plugin-result').textContent=JSON.stringify(r.result??r,null,2);notice('插件执行完成。');}catch(e){notice(e.message,true);$('plugin-result').textContent=e.message;}finally{run.disabled=false;}};actions.append(run);row.append(actions);$('plugins').append(row);}if(!list.length)$('plugins').textContent='宿主没有返回可用插件。';}catch(e){$('sdk-state').textContent='SDK 宿主未就绪';$('sdk-info').replaceChildren();sdkInfo('状态',e.message);$('plugins').textContent='启动宿主后读取插件。';}finally{sdkBusy=false;$('sdk-refresh').disabled=false;}}
async function sdkAction(action,button){button.disabled=true;try{const r=await api('/api/sdk/'+action,{});notice(r.message||'操作已提交');await sdkStatus();}catch(e){notice(e.message,true);}finally{button.disabled=false;}}
for(const action of ['start','stop','login'])$('sdk-'+action).onclick=e=>sdkAction(action,e.currentTarget);$('sdk-refresh').onclick=sdkStatus;$('devices-refresh').onclick=devices;$('settings-reload').onclick=loadConfig;$('log-task').onchange=()=>loadLogs().catch(e=>notice(e.message,true));$('copy-log').onclick=async()=>{try{await navigator.clipboard.writeText($('log').textContent);notice('日志已复制。');}catch{$('log').focus();const selection=window.getSelection(),range=document.createRange();range.selectNodeContents($('log'));selection.removeAllRanges();selection.addRange(range);notice('日志已选中，请长按或按 Ctrl+C 复制。');}};
document.querySelectorAll('[data-view]').forEach(b=>{b.onclick=()=>{currentView=b.dataset.view;document.querySelectorAll('[data-view]').forEach(x=>x.setAttribute('aria-selected',String(x===b)));document.querySelectorAll('[role=tabpanel]').forEach(x=>x.hidden=x.id!=='view-'+currentView);$('page-title').textContent=b.textContent.replace(/^\d+\s*/,'');if(currentView==='devices')devices();if(currentView==='settings'&&!configLoaded)loadConfig();if(currentView==='sdk')sdkStatus();};b.onkeydown=e=>{const tabs=[...document.querySelectorAll('[data-view]')];if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();tabs[(tabs.indexOf(b)+(e.key==='ArrowRight'?1:tabs.length-1))%tabs.length].focus();}};});
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh();});const requestedView=new URLSearchParams(location.search).get('view');if(['sdk','devices','settings'].includes(requestedView))document.querySelector('[data-view="'+requestedView+'"]').click();refresh();setInterval(refresh,3000);
</script></body></html>'''

